import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.DAaBRV8r.js";const i="/noc/retire-bw.png",u=JSON.parse(`{"title":"It's time","description":"","frontmatter":{"layout":"doc","title":"It's time","date":"2026-10-01T00:00:00.000Z"},"headers":[],"relativePath":"retire.md","filePath":"retire.md"}`),n={name:"retire.md"};function s(h,e,l,d,m,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="it-s-time" tabindex="-1">It&#39;s time <a class="header-anchor" href="#it-s-time" aria-label="Permalink to &quot;It&#39;s time&quot;">​</a></h1><h3 id="dear-colleagues" tabindex="-1">Dear Colleagues, <a class="header-anchor" href="#dear-colleagues" aria-label="Permalink to &quot;Dear Colleagues,&quot;">​</a></h3><p>After much thought and reflection, I would like to share with you that I have decided to retire by the end of this year.</p><p>I have spent many years away from home, building my career and embracing the opportunities and experiences that life has brought my way. The past 20 years in Qatar have been a particularly meaningful chapter of that journey. It has been a long and rewarding experience, filled with challenges, achievements, lasting friendships, and countless memories that I will always cherish. Qatar has been my home for two decades, and I am deeply grateful for all that this chapter of my life has given me.</p><p>I now feel that it is time for me to return home and devote more time to the people who matter most — our families, relatives, and friends. Most importantly, I want to be closer to and spend more precious time with our aging mother and mother-in-law. Life has reminded me that while work is an important part of our journey, there are moments and relationships that cannot be replaced or postponed.</p><p>As I prepare to close this chapter, I want to sincerely thank each of you for your friendship, support, cooperation, and the many wonderful memories we have shared over the years. It has been a privilege to work alongside such wonderful colleagues, and I am truly grateful for the relationships I have built during my career.</p><p>Although I am looking forward to retirement and returning home, saying goodbye to colleagues and friends is never easy. I hope that our paths will continue to cross, and that the friendships we have made will remain long after my working days come to an end.</p><p>Thank you once again for being part of my journey. I wish you and your families continued happiness, good health, and success.</p><h3 id="a-few-words-to-remember" tabindex="-1"><a href="/noc/memwall.html">A Few Words to Remember</a> <a class="header-anchor" href="#a-few-words-to-remember" aria-label="Permalink to &quot;[A Few Words to Remember](/memwall)&quot;">​</a></h3><p>As I begin this new chapter, I would be grateful if you could leave a few words, a message, or a favorite <a href="/noc/memwall.html">memory</a>. Your thoughts and wishes will be a wonderful reminder of the people and friendships that have made this journey so special.</p><p>Thank you for being part of my story.</p><p>With warmest regards,</p><p>Bao Ngo</p><p><img src="'+i+'" alt="retire in black and white"></p>',14)])])}const f=a(n,[["render",s]]);export{u as __pageData,f as default};
